#include "core.hpp"
#include <iostream>
int wmain(int argc,wchar_t** argv){try{if(argc<4)throw std::runtime_error("Usage: LauncherChecks ROOT ISOLATED_SAVES COMMAND [args]");wr::Store s(argv[1],true,argv[2]);std::wstring cmd=argv[3];if(cmd==L"seed"&&argc==8)s.Seed(argv[4],wr::Verify(wr::Read(argv[5])),argv[6],wr::Verify(wr::Read(argv[7])));else if(cmd==L"check"&&argc==5){auto info=s.Check(wr::Utf8(argv[4]));std::cout<<wr::json{{"gameAvailable",info.gameAvailable},{"musicAvailable",info.musicAvailable},{"musicBytes",info.musicBytes},{"added",info.added},{"changed",info.changed},{"removed",info.removed}}.dump();}else if(cmd==L"game"&&argc==5)s.InstallGame(wr::Verify(wr::Read(argv[4])));else if(cmd==L"cancel-game"&&argc==5){s.progress=[&](const std::string&,uint64_t,uint64_t){s.cancel=true;};s.InstallGame(wr::Verify(wr::Read(argv[4])));}else if(cmd==L"busy-game"&&argc==5){wchar_t exe[32768];GetModuleFileNameW(nullptr,exe,32768);s.SetRunning(GetCurrentProcessId(),exe,"fixture");s.InstallGame(wr::Verify(wr::Read(argv[4])));}else if(cmd==L"music"&&argc==5)s.InstallMusic(wr::Verify(wr::Read(argv[4])));else if(cmd==L"rollback")s.Rollback();else if(cmd==L"verify"&&argc==5)std::cout<<wr::Verify(wr::Read(argv[4])).dump();else if(cmd==L"status")std::cout<<s.state.dump(2);else throw std::runtime_error("Unknown fixture command");return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
